current, best, start, left, right := a[0], a[0], 0, 0, 0
for i := 1; i < len(a); i++ {
	if current < 0 {
		current = a[i]
		start = i
	} else {
		current += a[i]
	}
	if current > best {
		best, left, right = current, start, i
	}
}
fmt.Printf("max sum %d at [%d, %d]\n", best, left, right)
